335     if (!saved || saved.archivedAt || saved.generation?.runId !== generation.runId || saved.generation.chatId !== generation.chatId) throw Error('Generation target is unavailable');
336     if (!generationRunning(saved.generation)) {
337       if (equal(saved.generation, generation)) return;
338       throw Error('Generation has already settled');
339     }
340     if (proposed) {
341       if (generation.status !== 'finished') throw Error('Only completed generation can publish a view');
342       validateCanvasHistory(proposed);
343       const snapshot = structuredClone({ ...proposed.snapshots[proposed.headId], id: id('canvas-revision'), parentId: saved.finalCheckpointId });
344       delete snapshot.transactionId;
345       for (const [key, revision] of Object.entries(proposed.diagramRevisions)) {
346         if (this.record.diagramRevisions[key] && !equal(this.record.diagramRevisions[key], revision)) throw Error('Diagram revision is immutable');
347       }
348       const next = { ...this.record, snapshots: { ...this.record.snapshots, [snapshot.id]: snapshot },
349         diagramRevisions: { ...this.record.diagramRevisions, ...proposed.diagramRevisions },
350         revisionBoundary: { ...proposed.revisionBoundary, ...this.record.revisionBoundary } };
351       validateCanvasHistory(next);
352       for (const revision of Object.values(proposed.diagramRevisions)) diagramRevisions.register(revision);
353       Object.assign(this.record.diagramRevisions, proposed.diagramRevisions);
354       this.record.snapshots[snapshot.id] = snapshot;
355       this.record.revisionBoundary = next.revisionBoundary;
