501     (redo ? this.record.past : this.record.future).push(this.record.headId);
502     this.record.headId = target;
503     this.recordViewStep();
504     return this.head;
505   }
506   linkTransaction(transactionId: string) {
507     const snapshot = { ...this.record.snapshots[this.record.headId], transactionId };
508     this.record.snapshots[snapshot.id] = snapshot;
509     this.changes.push({ snapshots: { [snapshot.id]: snapshot }, diagramRevisions: {} });
510   }
511   retireTransactions(ids: ReadonlySet<string>) {
512     for (const prior of Object.values(this.record.snapshots)) if (prior.transactionId && ids.has(prior.transactionId)) {
