515       this.changes.push({ snapshots: { [snapshot.id]: snapshot }, diagramRevisions: {} });
516     }
517   }
518   /** Publish a reviewed state as one checkpoint, retaining its exact diagram revision IDs. */
519   adopt(proposed: CanvasHistoryRecord): void {
520     validateCanvasHistory(proposed);
521     for (const revision of Object.values(proposed.diagramRevisions)) diagramRevisions.register(revision);
522     const added = Object.fromEntries(Object.entries(proposed.diagramRevisions).filter(([key]) => !this.record.diagramRevisions[key]));
523     for (const [key, revision] of Object.entries(proposed.diagramRevisions)) {
