526     }
527     const snapshot = structuredClone({ ...proposed.snapshots[proposed.headId], id: id('canvas-revision'), parentId: this.record.headId });
528     const next = { ...this.record, snapshots: { ...this.record.snapshots, [snapshot.id]: snapshot },
529       diagramRevisions: { ...this.record.diagramRevisions, ...proposed.diagramRevisions },
530       past: [...this.record.past, this.record.headId], future: [], headId: snapshot.id };
