532     // Keep the revision table object used by the internal resolver alive.
533     Object.assign(this.record.diagramRevisions, structuredClone(proposed.diagramRevisions));
534     this.record = { ...next, diagramRevisions: this.record.diagramRevisions };
535     this.recordViewStep();
536     this.changes.push({ snapshots: { [snapshot.id]: snapshot }, diagramRevisions: Object.fromEntries(Object.keys(added).map(key => [key, this.record.diagramRevisions[key]])) });
537   }
538   reset(view?: unknown) {
539     this.validateCheckpoint(this.record.baselineId);
540     const baseline = this.record.snapshots[this.record.baselineId];
541     const snapshot = structuredClone({ ...baseline, id: id('canvas-revision'), parentId: this.record.headId, view: view ?? baseline.view });
542     this.record.snapshots[snapshot.id] = snapshot;
543     this.changes.push({ snapshots: { [snapshot.id]: snapshot }, diagramRevisions: {} });
544     this.record.past.push(this.record.headId);
545     this.record.headId = snapshot.id;
546     this.record.future = [];
547     this.recordViewStep();
548     return this.head;
549   }
