{
  "summary": "The codebase is a diagram authoring and experimentation system built around immutable diagram revisions and revision-bound canvas composition. Browser editing, agent tools, generated alternatives, and Git change proposals converge on shared canvas commands and history. Persistence, source evidence, reusable agent contexts, and evaluation workflows form the main supporting boundaries; static architecture analysis is a separate tooling subsystem.",
  "points": [
    {
      "id": "runtime",
      "title": "Runtime Composition and APIs",
      "rationale": "The backend composition root connects application services to filesystem stores, model runtimes, browser bridges, and language services. Its Vite adapter exposes the core and mapping APIs, translates errors, controls optional capabilities, and owns shutdown. This is the strongest anchor for understanding deployment and dependency wiring.",
      "sourcePaths": [
        "src/server/app/bootstrap.ts",
        "src/server/app/vitePlugin.ts",
        "src/server/routes/core/routes.ts",
        "src/server/routes/mapping/routes.ts",
        "vite.config.ts",
        "tests/architecture/dependencies.test.ts"
      ],
      "relationships": [
        {
          "pointId": "storage",
          "label": "Constructs and injects durable repositories",
          "kind": "ownership"
        },
        {
          "pointId": "agent-api",
          "label": "Wires canvas services and WebSocket transport",
          "kind": "ownership"
        },
        {
          "pointId": "chat",
          "label": "Constructs chat runtime and tool bindings",
          "kind": "ownership"
        },
        {
          "pointId": "changes",
          "label": "Connects push ingestion to proposal workflows",
          "kind": "ownership"
        },
        {
          "pointId": "evals",
          "label": "Assembles evaluation services and generation reconciliation",
          "kind": "ownership"
        }
      ]
    },
    {
      "id": "diagrams",
      "title": "Immutable Diagram Revisions",
      "rationale": "Diagram identity, parsed ASCII content, logical node continuity, source mappings, and revision ancestry meet here. Creation and editing issue validated immutable revisions; the runtime registry preserves their identity. This separates diagram content from its placements and provides the shared foundation for editing, generation, comparison, and persistence.",
      "sourcePaths": [
        "domain/core/diagrams/diagram.ts",
        "domain/core/diagrams/diagramContent.ts",
        "domain/core/diagrams/diagramContentNodes.ts",
        "domain/core/diagrams/asciiTree.ts",
        "domain/core/diagrams/diagramRevision.ts",
        "domain/core/diagrams/diagramRevisionEditor.ts",
        "domain/core/diagrams/diagramRevisionStore.ts",
        "domain/core/diagrams/submitDiagramEdit.ts"
      ],
      "relationships": []
    },
    {
      "id": "canvas",
      "title": "Canvas Commands and History",
      "rationale": "MappingDocumentController is the shared semantic mutation boundary for browser edits and isolated proposals. It validates versions and operation batches, coordinates placements and connections, and delegates checkpoints, named views, branching, and undo history to CanvasHistoryService. Canvas checkpoints bind exact diagram revisions independently of composition and personal view state.",
      "sourcePaths": [
        "domain/mapping/workspace/mappingDocumentController.ts",
        "domain/core/diagrams/canvasHistory.ts",
